using System;using System.Collections.Generic;public class MaxOrderedList{private List<int> elements;public MaxOrderedList(){elements=new List<int>();}public void Insert(int value){elements.Add(value);elements.Sort((a,b)=>b.CompareTo(a));}public int RemoveMax(){if(IsEmpty())throw new InvalidOperationException("The list is empty.");int max=elements[0];elements.RemoveAt(0);return max;}public int GetMax(){if(IsEmpty())throw new InvalidOperationException("The list is empty.");return elements[0];}public bool IsEmpty(){return elements.Count==0;}public int Count(){return elements.Count;}}